CREATE OR REPLACE FUNCTION public.seller_open_question_list(p_limit integer DEFAULT 5)
 RETURNS TABLE(id uuid, listing_id uuid, listing_title text, body text, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select q.id, q.listing_id, l.title, q.body, q.created_at
  from public.listing_questions q
  join public.listings l on l.id = q.listing_id
  where l.seller_id = auth.uid()
    and q.parent_id is null
    and not exists (select 1 from public.listing_questions a where a.parent_id = q.id)
  order by q.created_at desc
  limit least(greatest(coalesce(p_limit, 5), 1), 20);
$function$;

grant execute on function public.seller_open_question_list(p_limit integer) to authenticated;
